const entrada = $('Entrada solicitud').first().json;
const texto = valor => String(valor ?? '').trim();

const error = (codigo, mensaje) => [{
  json: {
    success: false,
    modo: 'VALIDACION_SIN_ESCRITURA',
    error_code: codigo,
    message: mensaje
  }
}];

const productoId = texto(entrada.producto_id);
const userId = texto(entrada.user_id);
const chatId = texto(entrada.chat_id);
const sessionId = texto(entrada.session_id);
const updateId = texto(entrada.update_id);
const cantidad = entrada.cantidad;

if (!productoId) {
  return error('PRODUCTO_ID_REQUERIDO', 'Falta identificar el producto.');
}

if (
  !/^\d+$/.test(userId) ||
  !/^\d+$/.test(chatId) ||
  !/^\d+$/.test(updateId)
) {
  return error(
    'CONTEXTO_INVALIDO',
    'Faltan identificadores válidos del solicitante o del mensaje.'
  );
}

if (sessionId !== `telegram:${chatId}:${userId}`) {
  return error(
    'SESION_INVALIDA',
    'La sesión no corresponde al chat y al usuario recibidos.'
  );
}

if (
  typeof cantidad !== 'number' ||
  !Number.isFinite(cantidad) ||
  cantidad <= 0
) {
  return error(
    'CANTIDAD_INVALIDA',
    'La cantidad debe ser un número mayor que cero.'
  );
}

const productos = $input.all()
  .map(item => item.json)
  .filter(row => texto(row.producto_id) === productoId);

if (productos.length === 0) {
  return error(
    'PRODUCTO_NO_ENCONTRADO',
    'No existe un producto con el identificador solicitado.'
  );
}

if (productos.length > 1) {
  return error(
    'PRODUCTO_ID_DUPLICADO',
    'Hay varias filas con el mismo producto_id. Revisa el inventario.'
  );
}

const producto = productos[0];
const activo = texto(producto.activo).toUpperCase();

if (!['TRUE', 'FALSE', 'SI', 'SÍ', 'NO'].includes(activo)) {
  return error(
    'ESTADO_ACTIVO_INVALIDO',
    'El producto no tiene un estado activo válido.'
  );
}

if (!['TRUE', 'SI', 'SÍ'].includes(activo)) {
  return error(
    'PRODUCTO_INACTIVO',
    'El producto está inactivo y no admite solicitudes de compra.'
  );
}

const nombreProducto = texto(producto.nombre_producto);
const unidad = texto(producto.unidad).toLowerCase();

if (!nombreProducto) {
  return error(
    'PRODUCTO_INCOMPLETO',
    'El producto no tiene un nombre válido.'
  );
}

const unidadesEnteras = ['bolsas', 'unidades', 'bultos'];
const unidadesFraccionarias = ['kg', 'litros'];

if (![...unidadesEnteras, ...unidadesFraccionarias].includes(unidad)) {
  return error(
    'UNIDAD_NO_ADMITIDA',
    'La unidad del producto requiere revisión antes de solicitar una compra.'
  );
}

if (unidadesEnteras.includes(unidad) && !Number.isSafeInteger(cantidad)) {
  return error(
    'CANTIDAD_ENTERA_REQUERIDA',
    `La cantidad para ${unidad} debe ser un entero válido.`
  );
}

return [{
  json: {
    success: true,
    modo: 'VALIDACION_SIN_ESCRITURA',
    solicitud_validada: {
      producto_id: productoId,
      nombre_producto: nombreProducto,
      cantidad,
      unidad,
      user_id: userId,
      chat_id: chatId,
      session_id: sessionId,
      nombre_usuario: texto(entrada.nombre_usuario),
      update_id: updateId,
      requiere_escalamiento: cantidad >= 50
    },
    message: 'Solicitud válida. Todavía no se guardó ningún borrador ni orden.'
  }
}];

const solicitud = $input.first().json.solicitud_validada;
const ahora = new Date();

const borradorId = [
  'BOR',
  solicitud.user_id,
  solicitud.update_id,
  solicitud.producto_id,
  solicitud.cantidad
].join('-');

return [{
  json: {
    borrador_id: borradorId,
    user_id: solicitud.user_id,
    chat_id: solicitud.chat_id,
    session_id: solicitud.session_id,
    producto_id: solicitud.producto_id,
    nombre_producto: solicitud.nombre_producto,
    cantidad: solicitud.cantidad,
    unidad: solicitud.unidad,
    estado: 'PENDIENTE_CONFIRMACION',
    creado_en: ahora.toISOString(),
    expira_en: new Date(ahora.getTime() + 15 * 60 * 1000).toISOString(),
    confirmado_en: '',
    orden_id: ''
  }
}];

const borrador = $('Preparar borrador').first().json;

return [{
  json: {
    success: true,
    action: 'BORRADOR_CREADO',
    persistido: true,
    borrador,
    requiere_escalamiento: borrador.cantidad >= 50,
    message: 'Borrador guardado en Sheets, pendiente de confirmación. No se creó una orden ni se notificó al encargado.'
  }
}];

const filas = $input.all().map(item => item.json);

if (filas.length !== 1) {
  return [{
    json: {
      success: false,
      error_code: 'BORRADOR_ID_DUPLICADO',
      message: 'Hay varias filas con el mismo borrador_id. Revisa la hoja antes de continuar.'
    }
  }];
}

const borrador = filas[0];
const esperado = $('Preparar borrador').first().json;

if (
  String(borrador.user_id) !== String(esperado.user_id) ||
  String(borrador.producto_id) !== String(esperado.producto_id) ||
  Number(borrador.cantidad) !== esperado.cantidad
) {
  return [{
    json: {
      success: false,
      error_code: 'BORRADOR_INCONSISTENTE',
      message: 'El borrador existente no coincide con la solicitud recibida.'
    }
  }];
}

return [{
  json: {
    success: true,
    action: 'BORRADOR_EXISTENTE',
    persistido: true,
    borrador,
    requiere_escalamiento: Number(borrador.cantidad) >= 50,
    message: 'El borrador ya existe. Se conservó su estado y sus fechas; no se creó otra fila ni una orden.'
  }
}];

const contexto = $('Normalizar callback').first().json;
const data = String(contexto.callback_data ?? '');
const separador = data.indexOf(':');

const accion = separador >= 0 ? data.slice(0, separador) : '';
const borradorId = separador >= 0 ? data.slice(separador + 1) : '';

if (
  contexto.tipo_chat !== 'private' ||
  !['confirmar', 'cancelar'].includes(accion) ||
  !/^BOR-[A-Za-z0-9.-]+$/.test(borradorId)
) {
  return [{
    json: {
      success: false,
      error_code: 'CALLBACK_INVALIDO',
      message: 'El botón no contiene una acción de borrador válida.',
      chat_id: contexto.chat_id
    }
  }];
}

return [{
  json: {
    success: true,
    accion,
    borrador_id: borradorId,
    user_id: String(contexto.user_id),
    chat_id: String(contexto.chat_id),
    message_id: String(contexto.message_id),
    callback_query_id: contexto.callback_query_id,
    recibido_en: contexto.recibido_en
  }
}];

const contexto = $('Interpretar acción de borrador').first().json;
const texto = valor => String(valor ?? '').trim();

const rechazar = (codigo, mensaje) => [{
  json: {
    success: false,
    error_code: codigo,
    message: mensaje,
    chat_id: texto(contexto.chat_id),
    borrador_id: texto(contexto.borrador_id)
  }
}];

const filas = $input.all()
  .map(item => item.json)
  .filter(row => texto(row.borrador_id) === texto(contexto.borrador_id));

if (filas.length === 0) {
  return rechazar(
    'BORRADOR_NO_ENCONTRADO',
    'No encontré el borrador. Solicita uno nuevo.'
  );
}

if (filas.length > 1) {
  return rechazar(
    'BORRADOR_ID_DUPLICADO',
    'Hay varias filas con el mismo borrador. Se requiere revisión.'
  );
}

const borrador = filas[0];

if (
  texto(borrador.user_id) !== texto(contexto.user_id) ||
  texto(borrador.chat_id) !== texto(contexto.chat_id)
) {
  return rechazar(
    'BORRADOR_NO_AUTORIZADO',
    'Este borrador no pertenece al usuario y chat que pulsaron el botón.'
  );
}

if (!['confirmar', 'cancelar'].includes(contexto.accion)) {
  return rechazar('ACCION_INVALIDA', 'La acción no es válida.');
}

if (texto(borrador.orden_id)) {
  return rechazar(
    'BORRADOR_CON_ORDEN',
    'Este borrador ya tiene una orden asociada.'
  );
}

if (texto(borrador.estado) !== 'PENDIENTE_CONFIRMACION') {
  return rechazar(
    'BORRADOR_NO_PENDIENTE',
    'El borrador ya no está pendiente de confirmación.'
  );
}

const expiracion = Date.parse(borrador.expira_en);

if (!Number.isFinite(expiracion)) {
  return rechazar(
    'EXPIRACION_INVALIDA',
    'El borrador no tiene una fecha de expiración válida.'
  );
}

if (Date.now() >= expiracion) {
  return rechazar(
    'BORRADOR_EXPIRADO',
    'El borrador expiró. Solicita uno nuevo.'
  );
}

const cantidad = borrador.cantidad;
const unidad = texto(borrador.unidad).toLowerCase();

if (
  typeof cantidad !== 'number' ||
  !Number.isFinite(cantidad) ||
  cantidad <= 0
) {
  return rechazar(
    'CANTIDAD_INVALIDA',
    'La cantidad guardada no es válida.'
  );
}

const enteras = ['bolsas', 'unidades', 'bultos'];
const fraccionarias = ['kg', 'litros'];

if (![...enteras, ...fraccionarias].includes(unidad)) {
  return rechazar(
    'UNIDAD_INVALIDA',
    'La unidad guardada requiere revisión.'
  );
}

if (enteras.includes(unidad) && !Number.isSafeInteger(cantidad)) {
  return rechazar(
    'CANTIDAD_ENTERA_REQUERIDA',
    'La cantidad guardada debe ser un entero válido.'
  );
}

if (!texto(borrador.producto_id)) {
  return rechazar(
    'PRODUCTO_ID_REQUERIDO',
    'El borrador no identifica un producto.'
  );
}

return [{
  json: {
    success: true,
    accion: contexto.accion,
    chat_id: texto(contexto.chat_id),
    user_id: texto(contexto.user_id),
    callback_query_id: contexto.callback_query_id,
    borrador,
    requiere_escalamiento: cantidad >= 50,
    validado_en: new Date().toISOString()
  }
}];

