const contexto = $('Validar acción sobre borrador').first().json;
const borrador = contexto.borrador;
const texto = valor => String(valor ?? '').trim();

const rechazar = (codigo, mensaje) => [{
  json: {
    success: false,
    error_code: codigo,
    message: mensaje,
    chat_id: contexto.chat_id
  }
}];

const productos = $input.all()
  .map(item => item.json)
  .filter(row =>
    texto(row.producto_id) === texto(borrador.producto_id)
  );

if (productos.length === 0) {
  return rechazar(
    'PRODUCTO_NO_ENCONTRADO',
    'El producto ya no está disponible en el inventario.'
  );
}

if (productos.length > 1) {
  return rechazar(
    'PRODUCTO_ID_DUPLICADO',
    'Hay varias filas para el producto. Se requiere revisión.'
  );
}

const producto = productos[0];

if (!['TRUE', 'SI', 'SÍ'].includes(texto(producto.activo).toUpperCase())) {
  return rechazar(
    'PRODUCTO_NO_ACTIVO',
    'El producto no tiene un estado activo válido para registrar la solicitud.'
  );
}

if (
  texto(producto.unidad).toLowerCase() !==
  texto(borrador.unidad).toLowerCase()
) {
  return rechazar(
    'UNIDAD_MODIFICADA',
    'La unidad del producto cambió. Solicita un borrador nuevo.'
  );
}

const expiracion = Date.parse(borrador.expira_en);

if (!Number.isFinite(expiracion) || Date.now() >= expiracion) {
  return rechazar(
    'BORRADOR_EXPIRADO',
    'El borrador expiró. Solicita uno nuevo.'
  );
}

return [{
  json: {
    ...contexto,
    success: true,
    producto_actual: producto,
    orden_id_propuesto: 'OC-' + texto(borrador.borrador_id).replace(/^BOR-/, '')
  }
}];

const contexto = $('Validar producto para confirmar').first().json;
const borrador = contexto.borrador;
const callback = $('Normalizar callback').first().json;

const expiracion = Date.parse(borrador.expira_en);

if (!Number.isFinite(expiracion) || Date.now() >= expiracion) {
  return [{
    json: {
      success: false,
      error_code: 'BORRADOR_EXPIRADO',
      message: 'El borrador expiró. Solicita uno nuevo.',
      chat_id: contexto.chat_id
    }
  }];
}

const requiereEscalamiento = Number(borrador.cantidad) >= 50;

return [{
  json: {
    success: true,
    orden: {
      orden_id: contexto.orden_id_propuesto,
      borrador_id: borrador.borrador_id,
      user_id: String(borrador.user_id),
      chat_id: String(borrador.chat_id),
      nombre_usuario: String(callback.nombre_usuario ?? ''),
      producto_id: borrador.producto_id,
      nombre_producto: borrador.nombre_producto,
      cantidad: Number(borrador.cantidad),
      unidad: borrador.unidad,
      estado: requiereEscalamiento
        ? 'PENDIENTE_APROBACION'
        : 'PENDIENTE_REVISION',
      creado_en: new Date().toISOString(),
      requiere_escalamiento: requiereEscalamiento,
      estado_notificacion: requiereEscalamiento
        ? 'PENDIENTE'
        : 'NO_REQUERIDA'
    }
  }
}];

